"""Own frozen complete Mac bundle; never launches or alters focus."""
from pathlib import Path
import sys,json,hashlib,shutil,plistlib,shlex
r=Path(__file__).resolve().parents[2];manifest=Path(sys.argv[1]).resolve();m=json.loads(manifest.read_text());assert m['owner']=='preflight'and m['component']=='capabilitytable'and m['runtime']=='osx-arm64'and m['buildExitCode']==0
binary=Path(m['binary']);assert hashlib.sha256(binary.read_bytes()).hexdigest()==m['binarySha256'];bundle=manifest.parent/'CapabilityTableCheck.app';assert not bundle.exists();mac=bundle/'Contents/MacOS';shutil.copytree(binary.parent,mac/'runtime');out=manifest.parent/'actual-macos';out.mkdir();(out/'input').mkdir();(out/'cases.json').write_bytes((r/'docs/replica/source/capabilitytable-cases.json').read_bytes());(out/'input-cases.json').write_bytes((r/'docs/replica/source/capabilitytable-input-cases.json').read_bytes())
(mac/'CapabilityTableCheck').write_text('#!/bin/sh\nexec '+shlex.quote(str(mac/'runtime/ReplicaProbe'))+' --capabilitytable-window '+shlex.quote(str(out/'input-cases.json'))+' '+shlex.quote(str(out/'input'))+'\n');(mac/'CapabilityTableCheck').chmod(0o755)
(bundle/'Contents/Info.plist').write_bytes(plistlib.dumps({'CFBundleIdentifier':'local.dbmv.replica.capabilitytablecheck','CFBundleExecutable':'CapabilityTableCheck','CFBundleName':'CapabilityTableCheck','CFBundlePackageType':'APPL','NSHighResolutionCapable':True}));(out/'bundle.json').write_text(json.dumps({'manifest':str(manifest),'bundle':str(bundle),'output':str(out),'nativeBinarySha256':m['binarySha256']},indent=2)+'\n');print(bundle);print(out)
